import assert from "node:assert/strict";
import { test } from "node:test";
import {
	GitError,
	formatBytes,
	formatDiffLines,
	formatLogLines,
	formatStatusSummary,
	existsMessage,
	isTransient,
	parseArgs,
	parseRepoSpec,
	repoTarget,
	shallowMessage,
	shortOid,
	slugOf,
	tooLargeMessage
} from "../index.js";

/* ------------------------------------------------------------ repo specs */

test("owner/name resolves to the GitHub https URL and a flat slug", () => {
	const spec = parseRepoSpec("isomorphic-git/isomorphic-git");
	assert.equal(spec.url, "https://github.com/isomorphic-git/isomorphic-git");
	assert.equal(spec.slug, "isomorphic-git-isomorphic-git");
	assert.equal(spec.host, "github.com");
});

test("a clone URL drops the .git suffix and trailing slashes", () => {
	const spec = parseRepoSpec("https://github.com/QtePP/deepseek-harness-harmony.git/");
	assert.equal(spec.url, "https://github.com/QtePP/deepseek-harness-harmony");
	assert.equal(spec.slug, "qtepp-deepseek-harness-harmony");
});

test("a non-GitHub host is part of the slug so two hosts cannot collide", () => {
	const spec = parseRepoSpec("https://gitlab.com/group/project");
	assert.equal(spec.slug, "gitlab.com-group-project");
});

test("scp-style remotes are rewritten to https", () => {
	const spec = parseRepoSpec("git@github.com:owner/repo");
	assert.equal(spec.url, "https://github.com/owner/repo");
	assert.equal(spec.slug, "owner-repo");
});

test("plain http, file and ssh are refused with a named code", () => {
	for (const raw of ["http://github.com/a/b", "file:///tmp/repo", "ssh://git@github.com/a/b"]) {
		assert.throws(() => parseRepoSpec(raw), (error) => {
			return error instanceof GitError && error.code === "GIT_BAD_REPO";
		}, raw);
	}
});

test("empty and malformed specs are refused", () => {
	for (const raw of ["", "   ", "not-a-repo", "owner/", "/name", "a/b/c/d"]) {
		assert.throws(() => parseRepoSpec(raw), (error) => error.code === "GIT_BAD_REPO", raw);
	}
});

test("slugOf keeps dots and dashes but strips anything path-like", () => {
	assert.equal(slugOf("", "Owner", "Repo"), "owner-repo");
	assert.equal(slugOf("git.example.com", "a", "b"), "git.example.com-a-b");
	assert.equal(slugOf("", "a b", "c/d"), "a-b-c-d");
});

/* ------------------------------------------------------------ containment */

test("clones land under repos/ inside the workspace", () => {
	assert.equal(repoTarget("/work", "owner-repo"), "/work/repos/owner-repo");
});

test("a slug that climbs out of the workspace is refused", () => {
	assert.throws(() => repoTarget("/work", "../../etc"), (error) => error.code === "GIT_OUT_OF_WORKSPACE");
});

/* --------------------------------------------------------------- formats */

test("formatBytes switches units at the round numbers", () => {
	assert.equal(formatBytes(0), "0 B");
	assert.equal(formatBytes(999), "999 B");
	assert.equal(formatBytes(2048), "2.0 KB");
	assert.equal(formatBytes(1048576), "1.0 MB");
	assert.equal(formatBytes(92.2 * 1048576), "92.2 MB");
});

test("shortOid is seven characters", () => {
	assert.equal(shortOid("0123456789abcdef"), "0123456");
	assert.equal(shortOid("abc"), "abc");
	assert.equal(shortOid(undefined), "");
});

test("formatLogLines prints oid, date and the first message line", () => {
	const lines = formatLogLines([{
		oid: "0123456789abcdef",
		commit: {
			message: "Fix the thing\n\nlong body",
			committer: { timestamp: 1795145518 }
		}
	}]);
	assert.equal(lines.length, 1);
	assert.match(lines[0], /^0123456 \d{4}-\d\d-\d\d Fix the thing$/);
});

test("formatLogLines tolerates a commit with no committer", () => {
	const lines = formatLogLines([{ oid: "abcdef1234", commit: { message: "only a subject" } }]);
	assert.equal(lines[0], "abcdef1 only a subject");
});

test("formatStatusSummary counts and caps the listed paths", () => {
	const rows = [
		{ type: "A", path: "a" }, { type: "M", path: "b" }, { type: "M", path: "c" }, { type: "D", path: "d" }
	];
	const summary = formatStatusSummary(rows, 2);
	assert.deepEqual([summary.added, summary.modified, summary.deleted], [1, 2, 1]);
	assert.deepEqual(summary.lines, ["A a", "M b"]);
});

test("formatDiffLines renders one row per path", () => {
	assert.deepEqual(formatDiffLines([{ type: "M", path: "src/x.ts" }]), ["M src/x.ts"]);
});

/* -------------------------------------------------------------- retry set */

test("transient network failures are retried, policy failures are not", () => {
	for (const code of ["ECONNRESET", "ETIMEDOUT", "EAI_AGAIN", "ENOTFOUND"]) {
		assert.equal(isTransient({ code }), true, code);
	}
	assert.equal(isTransient(new Error("socket hang up")), true);
	assert.equal(isTransient(new Error("HTTP 502 from github.com")), true);
	assert.equal(isTransient({ code: "GIT_TOO_LARGE" }), false);
	assert.equal(isTransient(new Error("repository not found")), false);
});

/* ----------------------------------------------------------- arg parsing */

test("parseArgs accepts every documented action", () => {
	for (const action of ["clone", "snapshot", "pull", "log", "diff", "status"]) {
		assert.equal(parseArgs({ action, repo: "a/b" }).action, action);
	}
});

test("parseArgs refuses an unknown action with the allowed list", () => {
	assert.throws(() => parseArgs({ action: "fetch", repo: "a/b" }), (error) => {
		return error.code === "GIT_BAD_ACTION" && /clone, snapshot, pull, log, diff, status/.test(error.message);
	});
});

test("parseArgs requires a repo", () => {
	assert.throws(() => parseArgs({ action: "clone" }), (error) => error.code === "GIT_BAD_REPO");
});

test("parseArgs keeps only the fields the action can use", () => {
	const input = parseArgs({ action: "diff", repo: "a/b", base: "main", head: "HEAD", limit: 12.9, ref: "" });
	assert.equal(input.base, "main");
	assert.equal(input.head, "HEAD");
	assert.equal(input.limit, 12);
	assert.equal(input.ref, undefined);
});

/* ---------------------------------------------------- refusal messages */

// These three were rewritten after a device run: the model read "needs more
// than 50 MB" as a pre-flight size check and told the user no pack bytes were
// downloaded, when the transfer had in fact aborted mid-stream.

test("tooLargeMessage says the transfer was aborted, with how far it got", () => {
	const message = tooLargeMessage("microsoft-vscode", 50, 6299474);
	assert.match(message, /exceeded the 50 MB limit/);
	assert.match(message, /after 6\.0 MB of transfer/);
	assert.match(message, /aborted mid-stream/);
	assert.match(message, /partial tree was deleted/);
	// The wording must not imply we knew the size before downloading.
	assert.doesNotMatch(message, /needs more than/);
});

test("tooLargeMessage reports a zero-byte abort honestly", () => {
	assert.match(tooLargeMessage("x", 50, 0), /after 0 B of transfer/);
});

test("existsMessage gives one legal move per repository kind", () => {
	const message = existsMessage("o/n");
	assert.match(message, /"pull" advances it if it has full history/);
	assert.match(message, /re-run "snapshot" after deleting it/);
	assert.match(message, /a snapshot cannot be pulled/);
});

test("shallowMessage tells pull the snapshot loop is closed", () => {
	const message = shallowMessage("o/n", "pull");
	assert.match(message, /depth-1 snapshot/);
	assert.match(message, /re-run "snapshot" to refresh/);
	assert.match(message, /use "clone" if this repository needs history/);
});

test("shallowMessage names the real cause for a default diff", () => {
	const message = shallowMessage("o/n", "diff");
	assert.match(message, /single commit/);
	assert.match(message, /no HEAD~1 to compare against/);
	assert.match(message, /pass base=<ref> and head=<ref>/);
});
